import React, { useState } from 'react';
import { Link } from 'react-router-dom';

export default function ForgotPassword() {
  const [email, setEmail] = useState('');
  const [sent, setSent] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setSent(true);
  };

  return (
    <div className="min-vh-100 d-flex align-items-center justify-content-center" style={{ background: 'linear-gradient(135deg,#4f46e5,#7c3aed)' }}>
      <div className="card card-mw shadow p-4" style={{ maxWidth: 420, width: '100%' }}>
        <h3 className="mb-3">Reset Password</h3>
        {sent ? (
          <div className="alert alert-success">
            If an account exists for {email}, reset instructions would be sent via Firebase Auth in production.
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <label className="form-label">Email</label>
              <input type="email" className="form-control" value={email} onChange={(e) => setEmail(e.target.value)} required />
            </div>
            <button className="btn btn-primary w-100">Send Reset Link</button>
          </form>
        )}
        <Link to="/login" className="d-block text-center mt-3">Back to login</Link>
      </div>
    </div>
  );
}
